check=root/'reviews/nine-sharing-sign16-shared-values-terminal-independent/check.py';assert sha(check)=='8ea33335c88381edc5056b39b20240fce0128a2159aae2834e21efeae703b552';subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
